import java.io.*;
import java.util.*;

public class lets_do {
    static class FastScanner {
        private InputStream in;
        private int c;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        public int nextInt() throws IOException {
            int val = 0;
            int sign = 1;
            c = in.read();
            while (c == ' ' || c == '\n' || c == '\r' || c == '\t') {
                c = in.read();
            }
            if (c == '+' || c == '-') {
                if (c == '-') sign = -1;
                c = in.read();
            }
            while (c >= '0' && c <= '9') {
                val = val * 10 + (c - '0');
                c = in.read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt();
        int b = fs.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = fs.nextInt();
        }
        int[] pe = new int[n];
        int[] po = new int[n];
        int e = 0, o = 0;
        for (int i = 0; i < n; i++) {
            if (a[i] % 2 == 0) e++;
            else o++;
            pe[i] = e;
            po[i] = o;
        }
        List<Integer> wlist = new ArrayList<>();
        for (int i = 1; i < n - 2; i += 2) {
            if (pe[i] == po[i]) {
                wlist.add(Math.abs(a[i + 1] - a[i]));
            }
        }
        int p = wlist.size();
        int[] w = new int[p];
        for (int i = 0; i < p; i++) {
            w[i] = wlist.get(i);
        }
        int[][] dp = new int[p + 1][b + 1];
        for (int i = 1; i <= p; i++) {
            for (int cap = 0; cap <= b; cap++) {
                dp[i][cap] = dp[i - 1][cap];
                if (w[i - 1] <= cap) {
                    dp[i][cap] = Math.max(dp[i][cap], dp[i - 1][cap - w[i - 1]] + 1);
                }
            }
        }
        System.out.println(dp[p][b]);
    }
}
